package ru.neverland.townymarket;
import java.util.*;import java.util.concurrent.*;import java.util.function.*;import org.bukkit.Bukkit;import org.bukkit.entity.Player;
import static ru.neverland.townymarket.MarketData.*;
/** Durable market phases are separated from actor checks, raw bank calls and acknowledged delivery. */
final class MarketSettlement {
 private final MarketJournal repo;private final MarketGateway gateway;private final MarketExecution execution;private final BiPredicate<Player,Order> authorized;private final MarketFunding funding=new MarketFunding();
 Function<UUID,Player> players=Bukkit::getPlayer;
 MarketSettlement(MarketJournal repo,MarketGateway gateway,MarketExecution execution,BiPredicate<Player,Order> authorized){this.repo=repo;this.gateway=gateway;this.execution=execution;this.authorized=authorized;}
 interface Checked<T>{T get()throws Exception;}
 private <T>CompletionStage<T> guarded(Checked<T> action){return execution.guarded(()->{try{return action.get();}catch(Exception e){throw new CompletionException(e);}});}
 private CompletionStage<Void> stage(Order o,Phase phase,long next,String note){return repo.put(o.phase(phase,next,note)).thenApply(v->null);}
 private static CompletionStage<Void> done(){return CompletableFuture.completedFuture(null);}
 CompletionStage<Void> advance(Order o,long now,long retry){try{
  if(o==null||o.finalized()||o.check()>now)return done();
  return switch(o.phase()){
   case PREPARED->{String blocked=now>=Math.addExact(o.created(),60000)?"Истёк срок неоплаченной покупки":gateway.ready(o);if(blocked!=null)yield stage(o,Phase.RETURNING,now,blocked);yield guarded(()->gateway.reserve(o)).thenCompose(status->{try{if(!status.equals("HELD")){if(Set.of("DELIVERED","PICKUP","CLAIM_PENDING","CLAIMED").contains(status))throw new IllegalStateException("Неоплаченный товар уже выдан");return stage(o,Phase.RETURNING,now,MarketPayments.stockNote(status));}return repo.put(o.phase(Phase.DEBIT_READY,now,"Товар зарезервирован; оплата подготовлена"),funding.freeze(o),now).thenApply(v->null);}catch(Exception e){return CompletableFuture.failedFuture(e);}});}
   case DEBIT_READY->startDebit(o,now);
   case DEBIT_PENDING->pollBudget(o,now);
   case PAID->paid(o,now,retry);
   case DELIVERED->stage(o,Phase.CREDIT_PENDING,now,"Выплата продавцу ожидает подтверждения").thenCompose(v->guarded(()->gateway.preparePayment(o,true))).thenCompose(execution::bank).thenCompose(applied->stage(repo.order(o.id()),applied?Phase.COMPLETE:Phase.DELIVERED,applied?now:now+retry,applied?(o.city()?"Доставлено в склад города":"Оплачено. Заберите покупку в меню рынка"):"Банк продавца недоступен; вызов не выполнялся"));
   case CREDIT_PENDING->done();
   case RETURNING->guarded(()->gateway.refund(o)).thenCompose(status->{if(Set.of("RETURNED","MISSING").contains(status))return stage(o,Phase.CANCELLED,now,o.note());if(Set.of("DELIVERED","PICKUP","CLAIM_PENDING","CLAIMED").contains(status))return CompletableFuture.failedFuture(new IllegalStateException("Неоплаченная покупка уже доставлена"));return stage(o,Phase.RETURNING,now+retry,MarketPayments.stockNote(status));});
   case COMPLETE,CANCELLED->guarded(()->gateway.receipt(o)).thenCompose(receipt->{if(o.phase()==Phase.COMPLETE&&!o.city()&&!Set.of("CLAIMED","MISSING").contains(receipt))return done();return guarded(()->{gateway.acknowledge(o);return true;}).thenCompose(v->repo.put(o.finish())).thenApply(v->null);});
  };
 }catch(Exception e){return CompletableFuture.failedFuture(e);}}
 private CompletionStage<Void> startDebit(Order o,long now)throws Exception{var payment=repo.image().payments().get(o.id());if(payment==null)throw new IllegalStateException("Нет сохранённого протокола покупки");if(now>=o.created()+60000)return stage(o,Phase.RETURNING,now,"Истёк срок неоплаченной покупки");String blocked=gateway.ready(o);if(blocked!=null)return stage(o,Phase.RETURNING,now,blocked);if(payment.terms()!=null)return stage(o,Phase.DEBIT_PENDING,now,"Казна подтверждает оплату");if(o.city()&&funding.installed())return stage(o,Phase.RETURNING,now,"Подключена городская казна; откройте новое подтверждение покупки");
  return stage(o,Phase.DEBIT_PENDING,now,"Списание ожидает точной квитанции").thenCompose(v->{var player=players.apply(o.actor());if(player==null)return CompletableFuture.completedFuture((Supplier<Boolean>)()->false);return execution.entity(player,o.created()+60000,()->player.isOnline()&&System.currentTimeMillis()<o.created()+60000&&authorized.test(player,o)?gateway.preparePayment(o,false):(Supplier<Boolean>)()->false);}).thenCompose(action->action==null?CompletableFuture.completedFuture(false):execution.bank(action)).thenCompose(paid->stage(repo.order(o.id()),paid?Phase.PAID:Phase.RETURNING,now,paid?"Оплата подтверждена":"Банковский вызов не выполнялся; товар возвращается"));
 }
 private CompletionStage<Void> pollBudget(Order o,long now)throws Exception{var payment=repo.image().payments().get(o.id());if(payment==null||payment.terms()==null)return done();var terms=payment.terms();var snapshot=funding.snapshot(terms);if("ABSENT".equals(snapshot.get("status"))){if(now>=o.created()+60000)return stage(o,Phase.RETURNING,now,"Платёж не был запрошен; срок согласия истёк");var player=players.apply(o.actor());if(player==null)return done();return execution.entity(player,o.created()+60000,()->player.isOnline()&&System.currentTimeMillis()<o.created()+60000&&authorized.test(player,o)).thenCompose(allowed->{if(allowed==null)return done();if(!allowed)return stage(o,Phase.RETURNING,now,"Право покупки изменилось до оплаты");return funding.poll(terms,true).thenCompose(result->budgetResult(o,result,now));});}return budgetResult(o,terms.result(snapshot),now);}
 private CompletionStage<Void> budgetResult(Order o,MarketFunding.Result result,long now){return switch(result){case PAID->stage(o,Phase.PAID,now,"Казна подтвердила точную оплату");case REJECTED->stage(o,Phase.RETURNING,now,"Казна отклонила оплату; товар возвращается");case WAIT,REVIEW->done();};}
 private CompletionStage<Void> paid(Order o,long now,long retry)throws Exception{var payment=repo.image().payments().get(o.id());if(payment!=null&&payment.terms()!=null&&payment.terms().result(funding.snapshot(payment.terms()))!=MarketFunding.Result.PAID)return done();return guarded(()->gateway.deliver(o)).thenCompose(status->{if(status.equals(o.city()?"DELIVERED":"PICKUP"))return stage(o,Phase.DELIVERED,now,"Товар передан; ожидает оплаты продавцу");if(Set.of("MISSING","RETURNED").contains(status))return CompletableFuture.failedFuture(new IllegalStateException("Оплаченный резерв потерян: "+o.id()));return stage(o,Phase.PAID,now+retry,MarketPayments.stockNote(status));});}
}
